import{_ as t,o as a,c as o,a6 as r}from"./chunks/framework.DIp0zHSV.js";const m=JSON.parse('{"title":"LCARdS Theme Profiles for HA-LCARS","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/ha-lcars-theme-profiles.md","filePath":"configuration/ha-lcars-theme-profiles.md","lastUpdated":1792162559000}'),l={name:"configuration/ha-lcars-theme-profiles.md"};function d(s,e,c,n,i,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="lcards-theme-profiles-for-ha-lcars" tabindex="-1">LCARdS Theme Profiles for HA-LCARS <a class="header-anchor" href="#lcards-theme-profiles-for-ha-lcars" aria-label="Permalink to &quot;LCARdS Theme Profiles for HA-LCARS&quot;">​</a></h1><p><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer"><strong>HA-LCARS</strong></a> includes two themes made for LCARdS: <strong>LCARS Picard [LCARdS Red Accent]</strong> and <strong>LCARS Picard [LCARdS Blue Accent]</strong>. Pick one and Home Assistant&#39;s own screens, the HA-LCARS chrome and your LCARdS cards all share one palette.</p><ul><li>Uses the <strong>LCARdS colour palette</strong> (<code>--lcards-*</code> variables) that are provided automatically by the integration.</li><li>The <strong>HA core colour tokens</strong> (<code>--ha-color-*</code>) which are used by stock Home Assistant components are remapped to LCARdS palette entries. This helps bring more theme consistency across across the UI.</li><li>All variables are assigned dynamic HA-LCARS/LCARdS palette references, meaning alert-mode hue rotations and light/dark mode switches propagate automatically.</li></ul><hr><h2 id="using-a-profile" tabindex="-1">Using a profile <a class="header-anchor" href="#using-a-profile" aria-label="Permalink to &quot;Using a profile&quot;">​</a></h2><ol><li>Install or update <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a> (the LCARdS profiles are part of its theme file; update if you don&#39;t see them).</li><li>In Home Assistant, open your <strong>Profile</strong> and pick <strong>LCARS Picard [LCARdS Red Accent]</strong> or <strong>LCARS Picard [LCARdS Blue Accent]</strong> as the theme.</li></ol><p>That&#39;s all: there is nothing to copy into <code>themes.yaml</code>.</p><p>To make your own profile, use the <a href="./ha-lcars-theme-lab.html">HA-LCARS Theme Lab</a> in the LCARdS panel: start from one of these profiles, change its palettes, and add the result to HA-LCARS.</p><hr><h2 id="available-profiles" tabindex="-1">Available Profiles <a class="header-anchor" href="#available-profiles" aria-label="Permalink to &quot;Available Profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profile name</th><th>Accent colour</th><th>Notes</th></tr></thead><tbody><tr><td><code>LCARS Picard [LCARdS Red Accent]</code></td><td>Orange/Red (<code>--lcards-orange-*</code>)</td><td>Primary accent mapped to the LCARdS orange family</td></tr><tr><td><code>LCARS Picard [LCARdS Blue Accent]</code></td><td>Blue (<code>--lcards-blue-*</code>)</td><td>Primary accent mapped to the LCARdS blue family</td></tr></tbody></table><p>Both profiles include independent <strong>light</strong> and <strong>dark</strong> mode sections and cover the full 11-shade HA core colour token range, plus HA&#39;s <code>on-*</code>/<code>fill-*</code>/<code>border-*</code>/<code>surface-*</code> semantic layer (the vars behind buttons, chips, form fields, and dialogs).</p><hr><h2 id="how-the-colour-mapping-works" tabindex="-1">How the Colour Mapping Works <a class="header-anchor" href="#how-the-colour-mapping-works" aria-label="Permalink to &quot;How the Colour Mapping Works&quot;">​</a></h2><h3 id="ha-core-colour-tokens" tabindex="-1">HA Core Colour Tokens <a class="header-anchor" href="#ha-core-colour-tokens" aria-label="Permalink to &quot;HA Core Colour Tokens&quot;">​</a></h3><p>Home Assistant&#39;s frontend exposes an 11-shade scale (05 → 95) for five colour families: <code>primary</code>, <code>neutral</code>, <code>orange</code>, <code>red</code>, and <code>green</code>. These are consumed by stock HA components. The profiles map each HA shade <strong>1:1</strong> to the matching stop on the <a href="./../core/themes/#lcards-css-colour-palette">LCARdS 11-stop palette scale</a>; LCARdS&#39;s own palette was expanded from its original 7 canon stops specifically so this mapping wouldn&#39;t need to lossily collapse multiple HA shades onto the same colour.</p><p>The family mapping differs per profile accent:</p><table tabindex="0"><thead><tr><th>HA family</th><th>Red Accent profile</th><th>Blue Accent profile</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-blue-*</code></td></tr><tr><td><code>neutral</code></td><td><code>--lcards-gray-*</code></td><td><code>--lcards-gray-*</code></td></tr><tr><td><code>orange</code></td><td><code>--lcards-yellow-*</code></td><td><code>--lcards-yellow-*</code></td></tr><tr><td><code>red</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-orange-*</code></td></tr><tr><td><code>green</code></td><td><code>--lcards-green-*</code></td><td><code>--lcards-green-*</code></td></tr></tbody></table><h3 id="semantic-tokens-text-on-fill-contrast" tabindex="-1">Semantic Tokens (text-on-fill contrast) <a class="header-anchor" href="#semantic-tokens-text-on-fill-contrast" aria-label="Permalink to &quot;Semantic Tokens (text-on-fill contrast)&quot;">​</a></h3><p>Remapping the shade scale alone isn&#39;t enough for readable text: HA computes button, chip, and form-field text colours (<code>--ha-color-on-*</code>) by referencing a fixed tone number within the same palette (e.g. &quot;text = tone 40 of whatever primary is&quot;), on the assumption that any colour a theme substitutes will still read clearly at that tone. That assumption doesn&#39;t hold equally for every hue: LCARdS&#39;s orange family has a narrower readable-lightness range than its blue family, which is why the Red Accent profile could otherwise generate low-contrast button text.</p><p>Both profiles now explicitly set the full <code>on-*</code>/<code>fill-*</code>/<code>border-*</code>/<code>surface-*</code> semantic layer, with every text/background pairing checked against real WCAG contrast math and corrected where HA&#39;s mechanical default would fail, rather than relying on the shade-scale remapping to produce readable results by chance. See <a href="./../development/ha-css-vars.html#layer-2-semantic-colour-tokens">ha-css-vars.md</a> for the full technical detail.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS repository</a></li><li><a href="./../core/themes/#lcards-css-colour-palette">LCARdS Colour Palette</a></li><li><a href="./../core/themes/">LCARdS Themes</a></li><li><a href="./../core/alert-mode.html">Alert Mode</a></li><li><a href="./../getting-started/installation.html">Installation</a></li></ul>',24)])])}const f=t(l,[["render",d]]);export{m as __pageData,f as default};
